byId("start-btn").addEventListener("click",()=>{
  current=0; answers=[]; finalKey=null; startedAt=Date.now();
  track("quiz_started"); renderQuestion(); showScreen("quiz");
});
byId("back-btn").addEventListener("click",()=>{if(current>0){current--;renderQuestion();track("back_clicked",{question:current+1});}});
byId("show-how-btn").addEventListener("click",()=>{resetStep=0;track("reset_started");renderHow();showScreen("how");});

byId("reset-next-btn").addEventListener("click",()=>{
  const flow = resetFlows[finalKey];
  track("reset_step_completed",{reset_step:resetStep+1});
  if(resetStep < flow.steps.length - 1){
    resetStep++;
    renderHow();
    window.scrollTo({top:0,behavior:"smooth"});
  } else {
    byId("complete-message").textContent = flow.complete;
    track("reset_completed");
    showScreen("complete");
  }
});
byId("back-result-btn").addEventListener("click",()=>showScreen("result"));
byId("restart-btn").addEventListener("click",()=>{
  track("restart_clicked");
  clearRenderedStudentState();
  SESSION_ID = newSessionId();
  lastActivityAt = Date.now();
  showScreen("start");
});

const sendDialog=byId("send-dialog");

function openDialog(dialog){
  if(typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open","");
}
function closeDialog(dialog){
  if(typeof dialog.close === "function") dialog.close();
  else dialog.removeAttribute("open");
}
function isValidEmail(value){
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value||"").trim());
}
function resetSendDialog(){
  const input=byId("destination-input");
  const status=byId("send-status");
  const button=byId("send-now-btn");
  input.value="";
  status.className="email-status";
  status.textContent="";
  button.disabled=false;
  button.innerHTML='SEND MY GLOW-UP <span>↗</span>';
}
function openEmailDialog(){
  resetSendDialog();
  track("send_opened",{channel:"email"});
  openDialog(sendDialog);
  setTimeout(()=>byId("destination-input").focus(),80);
}

byId("email-btn").addEventListener("click",openEmailDialog);
byId("send-dialog-close").addEventListener("click",()=>closeDialog(sendDialog));

byId("send-form").addEventListener("submit",async(e)=>{
  e.preventDefault();
  const email=byId("destination-input").value.trim();
  const status=byId("send-status");
  const button=byId("send-now-btn");

  if(!isValidEmail(email)){
    status.className="email-status error";
    status.textContent="Enter a valid email address.";
    return;
  }

  if(!CONFIG.endpoint){
    status.className="email-status error";
    status.textContent="Email sending still needs the Glow-Up send service connected in config.js.";
    track("send_failed",{channel:"email",error:"missing_endpoint"});
    return;
  }

  button.disabled=true;
  button.innerHTML='SENDING… <span>✦</span>';
  status.className="email-status info";
  status.textContent="Sending your Glow-Up…";
  track("send_attempted",{channel:"email"});

  try{
    const payload={
      action:"send_email",
      email,
      result:finalKey,
      subject:"Your Academic Reset Glow-Up",
      message:shareText(),
      html_message:shareHtml(),
      photo_base64:LIBRARIAN.portraitBase64,
      photo_mime:LIBRARIAN.portraitMime,
      session_id:SESSION_ID,
      program:CONFIG.program || "academic-reset-glow-up",
      location:CONFIG.location || "UW-Whitewater at Rock County"
    };

    const response=await fetch(CONFIG.endpoint,{
      method:"POST",
      headers:{"Content-Type":"text/plain;charset=utf-8"},
      body:JSON.stringify(payload)
    });
    const rawResponse=await response.text();
    let data={};
    try{ data=JSON.parse(rawResponse); }
    catch(_){ throw new Error("Send service returned an unreadable response"); }
    if(!response.ok || !data.ok) throw new Error(data.error||`Send failed (${response.status})`);

    status.className="email-status success";
    status.textContent="Sent ✦ Future you has receipts.";
    button.innerHTML='SENT <span>✓</span>';
    track("email_sent",{channel:"email",delivery:data.delivery||"backend"});
    byId("destination-input").value="";
  }catch(err){
    const msg=String(err && err.message ? err.message : err);
    status.className="email-status error";
    status.textContent="That didn’t send. Check the email address and send-service connection.";
    button.innerHTML='TRY AGAIN <span>↗</span>';
    track("send_failed",{channel:"email",error:msg.slice(0,120)});
  }finally{
    button.disabled=false;
  }
});

